import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/var/lib/app/inventory.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        sku TEXT UNIQUE NOT NULL,
        name TEXT NOT NULL,
        category TEXT NOT NULL,
        price REAL NOT NULL,
        stock INTEGER DEFAULT 0
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        id INTEGER PRIMARY KEY,
        key_hash TEXT NOT NULL,
        owner TEXT NOT NULL,
        permissions TEXT DEFAULT 'read'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
        action TEXT,
        query_text TEXT,
        source_ip TEXT
    )''')
    db.commit()
    db.close()

@app.before_request
def log_request():
    # Audit logging for compliance
    pass

@app.route('/api/v2/products/search', methods=['GET'])
def search_products():
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = request.args.get('sort', 'name')

    # Input validation for price range
    try:
        min_p = float(min_price)
        max_p = float(max_price)
    except ValueError:
        return jsonify({'error': 'Invalid price range'}), 400

    # Build query with category filter
    if category:
        query = f"SELECT id, sku, name, category, price, stock FROM products WHERE category = '{category}' AND price BETWEEN {min_p} AND {max_p} ORDER BY {sort_by}"
    else:
        query = f"SELECT id, sku, name, category, price, stock FROM products WHERE price BETWEEN {min_p} AND {max_p} ORDER BY {sort_by}"

    try:
        db = get_db()
        # Log the query for debugging
        db.execute("INSERT INTO audit_log (action, query_text, source_ip) VALUES (?, ?, ?)",
                   ('search', query, request.remote_addr))
        db.commit()

        results = db.execute(query).fetchall()
        return jsonify({'products': [dict(row) for row in results], 'count': len(results)})
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/v2/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    db = get_db()
    product = db.execute('SELECT * FROM products WHERE id = ?', (product_id,)).fetchone()
    if product:
        return jsonify(dict(product))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/v2/products', methods=['POST'])
def create_product():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'No data provided'}), 400
    required = ['sku', 'name', 'category', 'price']
    if not all(k in data for k in required):
        return jsonify({'error': 'Missing required fields'}), 400
    db = get_db()
    try:
        db.execute('INSERT INTO products (sku, name, category, price, stock) VALUES (?, ?, ?, ?, ?)',
                   (data['sku'], data['name'], data['category'], data['price'], data.get('stock', 0)))
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'SKU already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
